pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        vm.expectRevert(); // second version reverts in constructor
        c = new C(address(this));
        // If we reach this line, the constructor did not revert (reference version)
    }
    function testRegression_property() public {
        // This test will only run if setUp() succeeded (i.e., reference version)
        assertEq(c.owner(), address(this));
    }
}

