// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: send 1 ether to contract
        vm.deal(address(c), 1 ether);
        // Withdraw all to this test contract
        c.withdrawAll(address(this));
        // Now call a view function to check if contract still exists
        // In reference version this returns address(this) (owner)
        // In second version the contract selfdestructs, so call reverts
        try c.owner() returns (address) {
            assertTrue(true); // contract exists, assertion passes
        } catch {
            assertTrue(false); // contract destroyed, assertion fails
        }
    }
}
